<?php
require_once __DIR__.'/config/app.php';require_once __DIR__.'/config/koneksi.php';require_login();$pageTitle='Profil Saya';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$nama=trim($_POST['nama']??'');$old=$_POST['password_lama']??'';$new=$_POST['password_baru']??'';if($nama==='')$errors[]='Nama wajib diisi.';
 $q=$pdo->prepare("SELECT password FROM users WHERE id=?");$q->execute([current_user()['id']]);$hash=$q->fetchColumn();
 if($new!==''){if(!password_verify($old,$hash))$errors[]='Password lama tidak sesuai.';elseif(strlen($new)<8)$errors[]='Password baru minimal 8 karakter.';}
 if(!$errors){if($new!=='')$pdo->prepare("UPDATE users SET nama=?,password=? WHERE id=?")->execute([$nama,password_hash($new,PASSWORD_DEFAULT),current_user()['id']]);else $pdo->prepare("UPDATE users SET nama=? WHERE id=?")->execute([$nama,current_user()['id']]);$_SESSION['user']['nama']=$nama;flash('success','Profil berhasil diperbarui.');redirect('profil.php');}}
include __DIR__.'/partials/header.php';?>
<div class="page-head"><div><h1>Profil Saya</h1><div class="muted">Perbarui nama dan password akun.</div></div></div><?php foreach($errors as $x):?><div class="alert danger"><?=e($x)?></div><?php endforeach;?><div class="card" style="max-width:700px"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field full"><label>Nama</label><input name="nama" required value="<?=e(current_user()['nama'])?>"></div><div class="field full"><label>Username</label><input disabled value="<?=e(current_user()['username'])?>"></div><div class="field full"><label>Password lama (jika ingin mengganti)</label><input type="password" name="password_lama"></div><div class="field full"><label>Password baru (minimal 8 karakter)</label><input type="password" name="password_baru" minlength="8"></div></div><div class="form-actions"><button class="btn">Simpan Profil</button></div></form></div><?php include __DIR__.'/partials/footer.php';?>
